4	module CtrlUnit(
5	    input[31:0] inst,
6	    input cmp_res,
7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
8	        mem_r, rs1use, rs2use,
9	    output [1:0] hazard_optype,
10	    output [2:0] ImmSel, cmp_ctrl,
11	    output [3:0] ALUControl,
12	    output JALR, MRET,
13	
14	    output csr_rw, csr_w_imm_mux,
15	
16	    output[1:0] exp_vector
17	);
18	
19	    wire[6:0] funct7 = inst[31:25];
20	    wire[2:0] funct3 = inst[14:12];
21	    wire[6:0] opcode = inst[6:0];
22	
23	    wire Rop = opcode == 7'b0110011;
24	    wire Iop = opcode == 7'b0010011;
25	    wire Bop = opcode == 7'b1100011;
26	    wire Lop = opcode == 7'b0000011;
27	    wire Sop = opcode == 7'b0100011;
28	    wire CSRop = opcode == 7'b1110011;
29	
30	    wire funct7_0  = funct7 == 7'h0;
31	    wire funct7_32 = funct7 == 7'h20;
32	
33	    wire funct3_0 = funct3 == 3'h0;
34	    wire funct3_1 = funct3 == 3'h1;
35	    wire funct3_2 = funct3 == 3'h2;
36	    wire funct3_3 = funct3 == 3'h3;
37	    wire funct3_4 = funct3 == 3'h4;
38	    wire funct3_5 = funct3 == 3'h5;
39	    wire funct3_6 = funct3 == 3'h6;
40	    wire funct3_7 = funct3 == 3'h7;
41	
42	    wire ADD  = Rop & funct3_0 & funct7_0;
43	    wire SUB  = Rop & funct3_0 & funct7_32;
44	    wire SLL  = Rop & funct3_1 & funct7_0;
45	    wire SLT  = Rop & funct3_2 & funct7_0;
46	    wire SLTU = Rop & funct3_3 & funct7_0;
47	    wire XOR  = Rop & funct3_4 & funct7_0;
48	    wire SRL  = Rop & funct3_5 & funct7_0;
49	    wire SRA  = Rop & funct3_5 & funct7_32;
50	    wire OR   = Rop & funct3_6 & funct7_0;
51	    wire AND  = Rop & funct3_7 & funct7_0;
52	
53	    wire ADDI  = Iop & funct3_0;	
54	    wire SLTI  = Iop & funct3_2;
55	    wire SLTIU = Iop & funct3_3;
56	    wire XORI  = Iop & funct3_4;
57	    wire ORI   = Iop & funct3_6;
58	    wire ANDI  = Iop & funct3_7;
59	    wire SLLI  = Iop & funct3_1 & funct7_0;
60	    wire SRLI  = Iop & funct3_5 & funct7_0;
61	    wire SRAI  = Iop & funct3_5 & funct7_32;
62	
63	    wire BEQ = Bop & funct3_0;
64	    wire BNE = Bop & funct3_1;
65	    wire BLT = Bop & funct3_4;
66	    wire BGE = Bop & funct3_5;
67	    wire BLTU = Bop & funct3_6;
68	    wire BGEU = Bop & funct3_7;
69	
70	    wire LB =  Lop & funct3_0;
71	    wire LH =  Lop & funct3_1;
72	    wire LW =  Lop & funct3_2;
73	    wire LBU = Lop & funct3_4;
74	    wire LHU = Lop & funct3_5;
75	
76	    wire SB = Sop & funct3_0;
77	    wire SH = Sop & funct3_1;
78	    wire SW = Sop & funct3_2;
79	
80	    wire LUI   = opcode == 7'b0110111;
81	    wire AUIPC = opcode == 7'b0010111;
82	
83	    wire JAL  =  opcode == 7'b1101111;
84	    assign JALR = (opcode == 7'b1100111) && funct3_0;
85	
86	    wire CSRRW = CSRop & funct3_1;
87	    wire CSRRS = CSRop & funct3_2;
88	    wire CSRRC = CSRop & funct3_3;
89	    wire CSRRWI = CSRop & funct3_5;
90	    wire CSRRSI = CSRop & funct3_6;
91	    wire CSRRCI = CSRop & funct3_7;
92	
93	    assign MRET = inst == 32'b0011000_00010_00000_000_00000_1110011;
94	    wire ECALL = inst == 32'b0111_0011;
95	
96	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
97	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
98	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
99	    wire L_valid = LW | LH | LB | LHU | LBU;
100	    wire S_valid = SW | SH | SB;
101	    wire CSR_valid = CSRRW | CSRRS | CSRRC | CSRRWI | CSRRSI | CSRRCI;
102	
103	
104	    // Branch taken: conditional branch whose comparison holds, or an
105	    // unconditional jump (JAL/JALR). The target is computed in the ID stage.
106	    assign Branch = (B_valid & cmp_res) | JAL | JALR;
107	
108	    localparam Imm_type_I = 3'b001;
109	    localparam Imm_type_B = 3'b010;
110	    localparam Imm_type_J = 3'b011;
111	    localparam Imm_type_S = 3'b100;
112	    localparam Imm_type_U = 3'b101;
113	    assign ImmSel = Bop ? Imm_type_B :
114	                    JAL ? Imm_type_J :
115	                    Sop ? Imm_type_S :
116	                    (LUI | AUIPC) ? Imm_type_U :
117	                    Imm_type_I;
118	
119	    localparam cmp_EQ  = 3'b001;
120	    localparam cmp_NE  = 3'b010;
121	    localparam cmp_LT  = 3'b011;
122	    localparam cmp_LTU = 3'b100;
123	    localparam cmp_GE  = 3'b101;
124	    localparam cmp_GEU = 3'b110;
125	    assign cmp_ctrl = BEQ  ? cmp_EQ  :
126	                      BNE  ? cmp_NE  :
127	                      BLT  ? cmp_LT  :
128	                      BLTU ? cmp_LTU :
129	                      BGE  ? cmp_GE  :
130	                      BGEU ? cmp_GEU :
131	                      3'b000;
132	
133	    // 1 for AUIPC/JAL/JALR (uses PC), 0 for others (uses rs1)
134	    assign ALUSrc_A = AUIPC | JAL | JALR;
135	
136	    // 1 for immediate-type instructions, 0 for R-type
137	    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC | JAL | JALR;
138	
139	    localparam ALU_ADD  = 4'b0001;
140	    localparam ALU_SUB  = 4'b0010;
141	    localparam ALU_AND  = 4'b0011;
142	    localparam ALU_OR   = 4'b0100;
143	    localparam ALU_XOR  = 4'b0101;
144	    localparam ALU_SLL  = 4'b0110;
145	    localparam ALU_SRL  = 4'b0111;
146	    localparam ALU_SLT  = 4'b1000;
147	    localparam ALU_SLTU = 4'b1001;
148	    localparam ALU_SRA  = 4'b1010;
149	    localparam ALU_Ap4  = 4'b1011;
150	    localparam ALU_Bout = 4'b1100;
151	    assign ALUControl = (ADD | ADDI | L_valid | S_valid | AUIPC) ? ALU_ADD :
152	                        SUB ? ALU_SUB :
153	                        (AND | ANDI) ? ALU_AND :
154	                        (OR | ORI) ? ALU_OR :
155	                        (XOR | XORI) ? ALU_XOR :
156	                        (SLL | SLLI) ? ALU_SLL :
157	                        (SRL | SRLI) ? ALU_SRL :
158	                        (SLT | SLTI) ? ALU_SLT :
159	                        (SLTU | SLTIU) ? ALU_SLTU :
160	                        (SRA | SRAI) ? ALU_SRA :
161	                        (JAL | JALR) ? ALU_Ap4 :
162	                        LUI ? ALU_Bout :
163	                        ALU_ADD;
164	
165	    assign DatatoReg = L_valid | CSR_valid;
166	    assign RegWrite = R_valid | I_valid | LUI | AUIPC | JAL | JALR |
167	                      L_valid | CSR_valid;
168	    assign mem_w = S_valid;
169	    assign mem_r = L_valid;
170	    assign rs1use = R_valid | I_valid | B_valid | L_valid | S_valid | JALR |
171	                    CSRRW | CSRRS | CSRRC;
172	    assign rs2use = R_valid | B_valid | S_valid;
173	
174	    localparam hazard_optype_ALU = 2'd1;
175	    localparam hazard_optype_LOAD = 2'd2;
176	    localparam hazard_optype_STORE = 2'd3;
177	    assign hazard_optype = L_valid ? hazard_optype_LOAD :
178	                           S_valid ? hazard_optype_STORE :
179	                           (R_valid | I_valid | LUI | AUIPC | JAL | JALR |
180	                            CSR_valid) ? hazard_optype_ALU :
181	                           2'd0;
182	
183	    assign csr_rw = CSR_valid;
184	    assign csr_w_imm_mux = CSRRWI | CSRRSI | CSRRCI;
185	
186	    wire inst_valid = R_valid | I_valid | B_valid | L_valid | S_valid |
187	                      LUI | AUIPC | JAL | JALR | CSR_valid | MRET | ECALL;
188	    // exp_vector[1]: illegal instruction, exp_vector[0]: ecall
189	    assign exp_vector = {~inst_valid, ECALL};
190	
191	endmodule

